head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > M > getJSON]<br/>DataMap 모듈의 전체 데이터를 JSON 형식의 객체로 반환합니다.",
    "validation" : [
        "DataMap 모듈의 전체 데이터를 Key 가 정의된 순서대로 JSON 형식의 객체로 반환합니다.",
        "Key 의 ID 를 Key 로 'Key ID:Value' 형태의 Key-Value 쌍으로 구성됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }    

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // target 생성
    $c.gcm.createBasicDataMap();

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');

    scwin.btn_getJSON_onclick();
}



scwin.btn_getJSON_onclick = function (e) {
    let rtn = target1.getJSON();
    let jsonString = JSON.stringify(rtn);

    wf_body_bottom.getObj("scwin").setReturnValue("getJSON : " + jsonString);  
};
